"""Рецепты llm для заданий без генератора: аудирование, чтение, письмо, говорение (ЕГЭ 1–18, 37–42; ОГЭ 1–19, 35, устная часть).

Только структура по спецификациям и демоверсиям ФИПИ 2026 (ЕГЭ 2027 без изменений). Тексты не генерируются здесь:
рецепт описывает, что пишет модель, что проверяет скрипт и когда нужен второй проход вслепую. Примеры — собственные.
"""

COMMON = ('Тексты пишет модель по JSON-заданию (тема из кодификатора, уровень A2–B1 для ОГЭ, B1–B2 для ЕГЭ, длина); '
          'ключ строится из «фактов» задания, а не из текста; вторая модель решает вслепую; расхождение — брак; '
          'дедупликация по теме и нормализованному тексту; тексты ФИПИ и банков не используются.')


def L(id, exam, n, title, kes, invariant, varies, answer_rule, mistakes, recipe, example, n_range=None, oral=False, level='Б'):
    return {'id': id, 'exam': exam, 'n': n, 'n_range': n_range or str(n), 'title': title, 'kes': kes, 'level': level, 'invariant': invariant,
            'varies': varies, 'answer_rule': answer_rule, 'mistakes': mistakes, 'recipe': recipe + ' ' + COMMON, 'example': example, 'oral': oral}


